window.MG_LAZY_DATA["data/lazy/resources/security-v26-040-95e2c4efb7313c06.json"]={sha256:"95e2c4efb7313c06423c3dde816f3581f191326e01829da6c3eef240916b79f4",value:{"sources":[{"id":"v26-case-65223a8c9b41afa5","url":"https://docs.suricata.io/en/suricata-8.0.2/rules/thresholding.html","title":"Suricata 8.0.2 thresholding keywords","titleEn":"Suricata 8.0.2 thresholding keywords","publisher":"OISF","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-040","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-040","related":[{"id":"security-v26-041","referenceUrls":["https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9/html/using_selinux/index"],"title":"SELinux：型別標籤、DAC 與最小政策修復","titleEn":"SELinux: type labels, DAC and minimal policy repair","why":"用兩課的可觀察驗收條件比較模型邊界：4與3次僅對明示序列成立，第二來源不干擾；警報抑制與封鎖行為不混為一談。 交付12點狀態追蹤、三種門檻比較表與來源隔離測試。","whyEn":"Compare model boundaries using observable acceptance criteria: Counts 4 and 3 apply only to the stated sequence, sources remain independent and alert suppression is distinguished from blocking. Deliver a 12-point state trace, comparison of threshold types and source-isolation tests.","difference":"用合成ls -Z與AVC紀錄列服務domain、檔案type、物件class及permission；先查傳統權限，再查標籤與政策，不直接把整個系統設為permissive。","differenceEn":"Use synthetic ls -Z and AVC output to identify service domain, file type, object class and permission; inspect DAC, labels and policy instead of making the whole system permissive.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["在單一視窗、不跨重置邊界的教學序列，threshold告警數=floor(matches/N)；此式不套用其他門檻類型或封鎖動作。 同一來源12次匹配都在單一60秒窗內，N=3，起始計數為0。 floor(12/3)=4次告警；N改4時floor(12/4)=3次。","政策驗收矩陣=subject domains×object types×操作類別；允許DAC不代表SELinux允許，反之亦然。 基準4個服務domain、3個檔案type、2種讀寫操作，全部為紙面或隔離測試。 4×3×2=24案；新增第5個服務domain後5×3×2=30案。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["For this single-window teaching sequence, threshold alerts=floor(matches/N); do not apply the formula to other threshold types or blocking actions. One source has 12 matches in one 60-second window, N=3 and initial count zero. floor(12/3)=4 alerts; N=4 gives floor(12/4)=3.","Policy test matrix equals subject domains×object types×operation classes; DAC permission does not imply SELinux permission, or vice versa. Baseline has four service domains, three file types and two read/write operations in paper or isolated tests. 4×3×2=24 tests; adding a fifth service domain gives 5×3×2=30.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-050","referenceUrls":["https://github.com/linux-audit/audit-documentation"],"title":"Linux Audit：事件組裝、遺失計數與可追溯性","titleEn":"Linux Audit: event assembly, loss counters and traceability","why":"用兩課的可觀察驗收條件比較模型邊界：4與3次僅對明示序列成立，第二來源不干擾；警報抑制與封鎖行為不混為一談。 交付12點狀態追蹤、三種門檻比較表與來源隔離測試。","whyEn":"Compare model boundaries using observable acceptance criteria: Counts 4 and 3 apply only to the stated sequence, sources remain independent and alert suppression is distinguished from blocking. Deliver a 12-point state trace, comparison of threshold types and source-isolation tests.","difference":"以合成SYSCALL、PATH與CWD紀錄依事件序號與來源主機組裝；分開定義record數、event數與實際操作數，保留lost/backlog狀態。","differenceEn":"Assemble synthetic SYSCALL, PATH and CWD records by event serial and host; distinguish record, event and operation counts and retain lost/backlog state.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["在單一視窗、不跨重置邊界的教學序列，threshold告警數=floor(matches/N)；此式不套用其他門檻類型或封鎖動作。 同一來源12次匹配都在單一60秒窗內，N=3，起始計數為0。 floor(12/3)=4次告警；N改4時floor(12/4)=3次。","完整事件率=具所有所需紀錄的事件/預期事件；不能拿稽核行數直接當操作數，多筆紀錄不代表多次操作。 合成預期1000事件，960事件紀錄完整，40事件缺必要PATH或SYSCALL；每事件記錄數可不同。 960/1000×100=96%；修復30事件後990/1000×100=99%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["For this single-window teaching sequence, threshold alerts=floor(matches/N); do not apply the formula to other threshold types or blocking actions. One source has 12 matches in one 60-second window, N=3 and initial count zero. floor(12/3)=4 alerts; N=4 gives floor(12/4)=3.","Complete-event rate equals events with all required records divided by expected events; log-line count is not operation count because events span records. Expect 1000 synthetic events: 960 complete and 40 missing required PATH or SYSCALL, with variable record counts per event. 960/1000×100=96%; repairing 30 gives 990/1000×100=99%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-dfd605d35b18a1b8","url":"https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9/html/using_selinux/index","title":"RHEL 9: Using SELinux","titleEn":"RHEL 9: Using SELinux","publisher":"Red Hat","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-ab5f25dd0c0ced90","url":"https://github.com/linux-audit/audit-documentation","title":"Linux Audit documentation and specifications","titleEn":"Linux Audit documentation and specifications","publisher":"Linux Audit Project","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
